static void mochila(LinkedList<Objeto>L1,
                    LinkedList<Objeto>L2,
                    int max,int i){

    if(peso(L1)>max)return;

    if(!L1.isEmpty())
        System.out.println(L1);

    for(int k=i;k<L2.size();k++){
        L1.add(L2.get(k));
        mochila(L1,L2,max,k+1);
        L1.removeLast();
    }
}
